WITH all_rows(src,id,apr,apr_type) AS (SELECT 'apr',id,apr,typeof(apr) FROM apr UNION ALL SELECT 'customer',id,NULL,NULL FROM customer UNION ALL SELECT 'v1',id,apr,typeof(apr) FROM v1 UNION ALL SELECT 'v1rj',id,apr,typeof(apr) FROM v1rj UNION ALL SELECT 'v2',id,apr,typeof(apr) FROM v2 UNION ALL SELECT 'v2rj',id,apr,typeof(apr) FROM v2rj UNION ALL SELECT 'v2rjrj',id,apr,typeof(apr) FROM v2rjrj) SELECT src,id,apr,apr_type FROM all_rows ORDER BY src,id;